{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    edges = []
    for a, b, d in dists:
        u, v = (a, b) if a < b else (b, a)
        r = max(core[u], core[v], d)
        edges.append((r, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    selected = []
    total = 0.0
    need = len(nodes) - 1
    for r, u, v in edges:
        if union(u, v):
            selected.append({'nodes': [u, v], 'reachability': r})
            total += r
            if len(selected) == need:
                break
    if len(selected) != need:
        raise ValueError('Graph is disconnected')
    return {'edges': selected, 'total_weight': total}"
}
